create function public.midad_public_chapter_index(pid uuid) returns table(id uuid,title text,"position" integer,word_count bigint) language sql stable security definer set search_path='' as $$select c.id,c.title,c.position,coalesce((select sum(case when trim(s.plain_text)='' then 0 else cardinality(regexp_split_to_array(trim(s.plain_text),E'\\s+')) end) from public.midad_scenes s where s.chapter_id=c.id),0)::bigint from public.midad_publications pub join public.midad_chapters c on c.id=pub.chapter_id and c.draft_id is null join public.midad_books b on b.id=c.book_id where b.project_id=pid order by c.position,c.id$$;
create function public.midad_read_public_chapter(cid uuid) returns table(id uuid,title text,content jsonb,plain_text text) language sql stable security definer set search_path='' as $$select c.id,c.title,jsonb_build_object('type','doc','content',coalesce((select jsonb_agg(block order by s.position,s.id,block_no) from public.midad_scenes s cross join lateral jsonb_array_elements(s.content->'content') with ordinality as blocks(block,block_no) where s.chapter_id=c.id),'[]'::jsonb)),coalesce((select string_agg(s.plain_text,E'\n\n' order by s.position,s.id) from public.midad_scenes s where s.chapter_id=c.id),'') from public.midad_publications pub join public.midad_chapters c on c.id=pub.chapter_id and c.draft_id is null where c.id=cid$$;
revoke all on function public.midad_public_chapter_index(uuid),public.midad_read_public_chapter(uuid) from public;
grant execute on function public.midad_public_chapter_index(uuid),public.midad_read_public_chapter(uuid) to anon,authenticated;
